// EVM-side ScaledUI utilities — detection, read planning, and metadata parsing.
// Pure functions, no React; the app layer wires react-query + caching on top.
//
// Two dialects expose the same display-multiplier concept: `erc8056` (`uiMultiplier()` + ERC-165)
// and `b20` (Base's native standard: `multiplier()`, no ERC-165 — see ./b20). Both produce the same
// ScaledUIAmountMetadata, and the math is identical (1e18 == B20's WAD_PRECISION()).
//
// `buildScaledUIAmountReads` + `parseScaledUIAmountReads` are the shared plan/parse pair used by
// BOTH the fetcher below and the app's useScaledUIAmountMetadata hook, so the two can't drift.

import { SCALED_UI_DENOMINATOR } from '@pancakeswap/swap-sdk-core'
import type { Address, PublicClient } from 'viem'
import { b20AssetAbi } from './abis/B20'
import { erc165Abi } from './abis/ERC165'
import { scaledUIAmountAbi } from './abis/ScaledUIAmount'
import { isB20AssetToken } from './b20'

/** ERC-8056 ERC-165 ids. B20 claims none of them — its `supportsInterface` reverts outright. */
export const SCALED_UI_AMOUNT_INTERFACE_ID = '0xa60bf13d' as const
export const SCALED_UI_AMOUNT_BALANCES_INTERFACE_ID = '0xd890fd71' as const

export type ScaledUIDialect = 'erc8056' | 'b20'

export type ScaledUIAmountReadFn = 'uiMultiplier' | 'multiplier' | 'newUIMultiplier' | 'effectiveAt'

interface ScaledUIDialectSpec {
  /** Ordered candidates for the active multiplier; first success wins. */
  multiplierFns: readonly ScaledUIAmountReadFn[]
  /** Optional in ERC-8056 and absent on B20 pre-#173, so reads use `allowFailure`. */
  pendingFns: readonly ScaledUIAmountReadFn[]
}

const DIALECTS: Record<ScaledUIDialect, ScaledUIDialectSpec> = {
  erc8056: {
    // Deliberately no `multiplier()` fallback: it's a generic name that leverage/rebasing tokens
    // use for unrelated values, so reading it off an arbitrary token would corrupt displayed
    // amounts. Safe in the b20 dialect only because that's gated on a verified B20 address.
    multiplierFns: ['uiMultiplier'],
    pendingFns: ['newUIMultiplier', 'effectiveAt'],
  },
  b20: {
    // `multiplier()` first — the only getter that resolves today. `uiMultiplier()` is kept for
    // forward-compat: it starts working as an alias once base-std #173 reaches mainnet.
    multiplierFns: ['multiplier', 'uiMultiplier'],
    pendingFns: ['newUIMultiplier', 'effectiveAt'],
  },
}

const ABI_BY_FN = {
  uiMultiplier: scaledUIAmountAbi,
  newUIMultiplier: scaledUIAmountAbi,
  effectiveAt: scaledUIAmountAbi,
  multiplier: b20AssetAbi,
} as const satisfies Record<ScaledUIAmountReadFn, unknown>

/** A conventional ERC-8056 token deployed on Base still gets the `erc8056` dialect. */
export function resolveScaledUIDialect(chainId?: number, address?: string | null): ScaledUIDialect {
  return isB20AssetToken(chainId, address) ? 'b20' : 'erc8056'
}

export interface ScaledUIAmountRead {
  address: Address
  abi: (typeof ABI_BY_FN)[ScaledUIAmountReadFn]
  functionName: ScaledUIAmountReadFn
  chainId?: number
}

/** Shape shared by viem `multicall` and wagmi `useReadContracts` result entries. */
export interface ScaledUIAmountReadResult {
  status: 'success' | 'failure'
  result?: unknown
}

/** Positional — `parseScaledUIAmountReads` must be called with the same dialect. */
export function buildScaledUIAmountReads(params: {
  address: Address
  chainId?: number
  dialect: ScaledUIDialect
}): ScaledUIAmountRead[] {
  const { address, chainId, dialect } = params
  const spec = DIALECTS[dialect]
  return [...spec.multiplierFns, ...spec.pendingFns].map((functionName) => ({
    address,
    abi: ABI_BY_FN[functionName],
    functionName,
    ...(chainId === undefined ? {} : { chainId }),
  }))
}

const asBigInt = (entry: ScaledUIAmountReadResult | undefined): bigint | undefined =>
  entry?.status === 'success' && typeof entry.result === 'bigint' ? entry.result : undefined

/**
 * Live ScaledUI metadata for a token. Consumers should treat `{ enabled: false, multiplier: 1e18 }`
 * as the identity case and early-out from any scaling logic.
 */
export type ScaledUIAmountMetadata = {
  enabled: boolean
  /** 18-decimal fixed point. Defaults to `1e18` (identity). */
  multiplier: bigint
  newMultiplier?: bigint
  /** Unix seconds. */
  effectiveAt?: number
}

/** Returned for non-scaled tokens and on any read failure; behaves like a normal ERC-20. */
export const IDENTITY_SCALED_UI_AMOUNT_METADATA: ScaledUIAmountMetadata = {
  enabled: false,
  multiplier: SCALED_UI_DENOMINATOR,
}

export function parseScaledUIAmountReads(
  results: readonly ScaledUIAmountReadResult[],
  dialect: ScaledUIDialect,
): ScaledUIAmountMetadata {
  const spec = DIALECTS[dialect]
  const multiplierCount = spec.multiplierFns.length

  let multiplier: bigint | undefined
  for (let i = 0; i < multiplierCount; i++) {
    const candidate = asBigInt(results[i])
    // Zero is invalid in both standards, but a buggy contract could return it — letting it through
    // would collapse displayed amounts to zero and divide-by-zero on parse.
    if (candidate !== undefined && candidate !== 0n) {
      multiplier = candidate
      break
    }
  }
  if (multiplier === undefined) return IDENTITY_SCALED_UI_AMOUNT_METADATA

  const pendingIndex = (fn: ScaledUIAmountReadFn) => {
    const offset = spec.pendingFns.indexOf(fn)
    return offset === -1 ? -1 : multiplierCount + offset
  }

  const newMultiplier = asBigInt(results[pendingIndex('newUIMultiplier')])
  const effectiveAtRaw = asBigInt(results[pendingIndex('effectiveAt')])
  const effectiveAt = effectiveAtRaw !== undefined ? Number(effectiveAtRaw) : undefined

  // B20 post-#173 MIRRORS `uiMultiplier()` when nothing is scheduled, so the `!==` is load-bearing.
  const hasPending =
    newMultiplier !== undefined && effectiveAt !== undefined && newMultiplier !== multiplier && effectiveAt > 0

  return hasPending ? { enabled: true, multiplier, newMultiplier, effectiveAt } : { enabled: true, multiplier }
}

/**
 * A perf gate, not a correctness gate — `fetchScaledUIAmountMetadata` falls back to identity anyway
 * if the reads revert. Callers cache both outcomes (asymmetric TTL in IndexedDB).
 */
export async function probeIsScaledUIAmount(
  client: PublicClient,
  address: Address,
  chainId?: number,
): Promise<boolean> {
  // B20 reverts on `supportsInterface` for every id, so ERC-165 can never detect it.
  if (isB20AssetToken(chainId ?? client.chain?.id, address)) return true

  try {
    const result = await client.readContract({
      address,
      abi: erc165Abi,
      functionName: 'supportsInterface',
      args: [SCALED_UI_AMOUNT_INTERFACE_ID],
    })
    return Boolean(result)
  } catch {
    return false
  }
}

/** Safe against any contract — won't throw. */
export async function fetchScaledUIAmountMetadata(
  client: PublicClient,
  address: Address,
  chainId?: number,
): Promise<ScaledUIAmountMetadata> {
  const dialect = resolveScaledUIDialect(chainId ?? client.chain?.id, address)
  const results = await client.multicall({
    contracts: buildScaledUIAmountReads({ address, dialect }),
    allowFailure: true,
  })
  return parseScaledUIAmountReads(results as readonly ScaledUIAmountReadResult[], dialect)
}

export {
  SCALED_UI_DENOMINATOR,
  SCALED_UI_MULTIPLIER_DECIMALS,
  fromScaledUIAmount,
  isIdentityScaledUIMultiplier,
  toScaledUIAmount,
} from '@pancakeswap/swap-sdk-core'
