import { ChainId, getChainConfig } from '@pancakeswap/chains'
import invariant from 'tiny-invariant'
import { Currency, Token, NativeCurrency } from '@pancakeswap/swap-sdk-core'

import { WNATIVE, NATIVE } from '../constants'

/**
 *
 * Native is the main usage of a 'native' currency, i.e. for BSC mainnet and all testnets
 */
export class Native extends NativeCurrency {
  protected constructor({
    chainId,
    decimals,
    name,
    symbol,
  }: {
    chainId: number
    decimals: number
    symbol: string
    name: string
  }) {
    super(chainId, decimals, symbol, name)
  }

  public get wrapped(): Token {
    const wnative = WNATIVE[this.chainId as keyof typeof WNATIVE]
    invariant(!!wnative, 'WRAPPED')
    return wnative
  }

  private static cache: { [chainId: number]: Native } = {}

  /**
   * The chain's RPC-native currency.
   *
   * On a chain that wraps nothing, this instance is a hazard rather than a convenience: its
   * `wrapped` getter throws, and the repo has ~900 unguarded `.wrapped` reads, so one leaking
   * into the UI takes a page down somewhere far from where it was created. Those chains are
   * meant to go through `resolveNativeCurrency`, which hands back the ERC-20 they declare.
   *
   * Constructing one anyway is therefore almost always a mistake, and this fails loudly at the
   * point of construction — where it can be traced — rather than five frames deep in a getter
   * on an unrelated screen. Only outside production: a wrong page beats a blank one, and the
   * existing behaviour is what ships today.
   *
   * Gas and balance arithmetic genuinely needs the RPC native and its decimals. Those call
   * sites use {@link getRpcNative}, which is greppable, so they read as a deliberate whitelist
   * instead of disappearing into the same 81 anonymous `Native.onChain` calls.
   */
  public static onChain(chainId: number): Native {
    if (process.env.NODE_ENV !== 'production' && getChainConfig(chainId as ChainId)?.gasTokenOverride) {
      throw new Error(
        `Native.onChain(${chainId}): this chain settles gas in an ERC-20 and wraps nothing, so a native ` +
          `currency here has no .wrapped and will throw wherever it is read. Use resolveNativeCurrency(chainId) ` +
          `for the product's base asset, or getRpcNative(chainId) if you really need raw gas/balance decimals.`,
      )
    }
    return Native.rpcNative(chainId)
  }

  /** @internal shared by `onChain` and `getRpcNative` — the actual construction. */
  public static rpcNative(chainId: number): Native {
    if (chainId in this.cache) {
      return this.cache[chainId]
    }
    invariant(!!NATIVE[chainId as keyof typeof NATIVE], 'NATIVE_CURRENCY')
    const { decimals, name, symbol } = NATIVE[chainId as keyof typeof WNATIVE]
    // eslint-disable-next-line no-return-assign
    return (this.cache[chainId] = new Native({ chainId, decimals, symbol, name }))
  }

  public equals(other: Currency): boolean {
    return other.isNative && other.chainId === this.chainId
  }
}
