import { ChainId, getChainConfig } from '@pancakeswap/chains'
import type { Currency } from '@pancakeswap/swap-sdk-core'
import { Native } from './entities/native'
import { ERC20Token } from './entities/erc20Token'

const cache = new Map<number, Currency>()

/**
 * The currency the product should treat as a chain's base asset.
 *
 * On nearly every chain that is the RPC native, and this returns `Native.onChain(chainId)`
 * unchanged. The exception is a chain that settles gas in an ordinary ERC-20: Arc's native
 * USDC already satisfies IERC20, so nothing wraps it and `wrappedNativeCurrency` is null,
 * which makes a native `Currency` there a liability — `.wrapped` throws, and roughly a
 * hundred call sites read it without asking.
 *
 * Rather than patch each of those, the app simply never materialises such a native: this
 * returns the ERC-20 the chain declares for the same balance (`gasTokenOverride`), which is
 * also what its pools are keyed by and what a user means when they name the asset.
 *
 * NOT for gas arithmetic. `eth_getBalance`, gasPrice and gasLimit are denominated in the RPC
 * native's decimals, and on Arc that is 18 against the ERC-20's 6 — measured on chain, the two
 * views of one balance differ by exactly 1e12. Anything converting a raw wei figure must keep
 * using `NATIVE[chainId]` / `Native.onChain` and rescale explicitly.
 */
export function resolveNativeCurrency(chainId: number): Currency {
  const cached = cache.get(chainId)
  if (cached) return cached

  const gasToken = getChainConfig(chainId as ChainId)?.gasTokenOverride
  const resolved: Currency = gasToken
    ? new ERC20Token(chainId, gasToken.address as `0x${string}`, gasToken.decimals, gasToken.symbol, gasToken.name)
    : Native.onChain(chainId)

  cache.set(chainId, resolved)
  return resolved
}

/**
 * True when the chain's base asset is an ERC-20 rather than an unwrappable native, i.e. when
 * {@link resolveNativeCurrency} returns something that is not `isNative`.
 */
export function hasErc20GasToken(chainId: number): boolean {
  return Boolean(getChainConfig(chainId as ChainId)?.gasTokenOverride)
}

/**
 * The RPC-native currency, for the places that genuinely need it.
 *
 * `eth_getBalance`, `gasPrice`, `gasLimit` and anything else denominated in wei are in the
 * chain's native decimals, which on a chain with a differently-scaled ERC-20 base asset is not
 * the same scale as {@link resolveNativeCurrency} — Arc's two views of one balance were measured
 * 1e12 apart. Those raw figures must be paired with this, never with the product base asset.
 *
 * This exists so the handful of legitimate uses are greppable and reviewable, rather than
 * indistinguishable from an accidental `Native.onChain`.
 */
export function getRpcNative(chainId: number): Native {
  return Native.rpcNative(chainId)
}

/**
 * `getRpcNative` for a chain id that may not be an EVM chain at all.
 *
 * `Native.rpcNative` asserts `NATIVE[chainId]` exists, so handing it a non-EVM id (Solana) throws
 * `Invariant failed`. Hooks that read a native balance run on whatever chain the page happens to
 * be on, so they need to ask rather than assert.
 */
export function tryGetRpcNative(chainId?: number): Native | undefined {
  if (!chainId) return undefined
  try {
    return Native.rpcNative(chainId)
  } catch {
    return undefined
  }
}
